package com.greenocean.backend;
import com.greenocean.backend.auth.dto.*;import com.greenocean.backend.auth.service.*;import com.greenocean.backend.assistance.service.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.ObjectMapper;import java.util.*;import java.time.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseEFSessionIntegrationTest {
 @Autowired MockMvc mvc;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;@Autowired RegistrationService registration;@Autowired OutboxCipher cipher;@Autowired AssistanceService assistance;@Autowired org.springframework.transaction.PlatformTransactionManager manager;@Autowired jakarta.persistence.EntityManager entities;
 String password="A synthetic EF authentication passphrase";
 @BeforeEach void rates(){var tx=new org.springframework.transaction.support.TransactionTemplate(manager);tx.setPropagationBehavior(3);tx.executeWithoutResult(s->db.update("DELETE FROM auth_rate_windows"));}
 String account(){String email="ef-"+UUID.randomUUID()+"@example.test";registration.register(new RegisterRequest(email,password,null,null,null,"IR",null,null,true,1));db.update("UPDATE users SET status='ACTIVE',email_verified=TRUE WHERE email=?",email);entities.clear();return email;}
 ResultActions postJson(String path,Object data)throws Exception{return mvc.perform(post(path).contentType("application/json").content(json.writeValueAsString(data)));}
 TokenResponse login(String email)throws Exception{return json.readValue(postJson("/api/v1/auth/login",Map.of("email",email,"password",password,"deviceName","دستگاه 🌊\nsynthetic")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(),TokenResponse.class);}
 UUID sid(TokenResponse t){try{return UUID.fromString(json.readTree(Base64.getUrlDecoder().decode(t.accessToken().split("\\.")[1])).get("sid").asText());}catch(Exception e){throw new RuntimeException(e);}}
 UUID uid(String email){return db.queryForObject("SELECT id FROM users WHERE email=?",UUID.class,email);}
 void me(TokenResponse t,int code)throws Exception{mvc.perform(get("/api/v1/auth/me").header("Authorization","Bearer "+t.accessToken())).andExpect(status().is(code));}
 @Test @Tag("happy") void nativeAndWebSessionsHaveApprovedImmutableOverallBounds()throws Exception{
  String email=account();TokenResponse nativeToken=login(email);UUID nativeId=sid(nativeToken);assertThat(db.queryForObject("SELECT client_type FROM user_sessions WHERE id=?",String.class,nativeId)).isEqualTo("MOBILE");assertThat(db.queryForObject("SELECT extract(epoch from overall_expires_at-created_at)::bigint FROM user_sessions WHERE id=?",Long.class,nativeId)).isEqualTo(2592000L);
  var web=mvc.perform(post("/api/v1/auth/web/login").header("Origin","http://localhost:8081").header("X-GreenOcean-CSRF","1").contentType("application/json").content(json.writeValueAsString(Map.of("email",email,"password",password,"clientType","MOBILE")))).andExpect(status().isOk()).andReturn().getResponse();
  var body=json.readValue(web.getContentAsString(),TokenResponse.class);UUID webId=sid(body);assertThat(body.refreshToken()).isEqualTo("cookie");assertThat(web.getHeader("Set-Cookie")).contains("HttpOnly","SameSite=Strict","Path=/api/v1/auth/web","Max-Age=86400").doesNotContain("Domain=");assertThat(db.queryForObject("SELECT extract(epoch from overall_expires_at-created_at)::bigint FROM user_sessions WHERE id=?",Long.class,webId)).isEqualTo(86400L);
  var before=db.queryForMap("SELECT overall_expires_at,idle_expires_at,last_activity_at FROM user_sessions WHERE id=?",nativeId);postJson("/api/v1/auth/refresh",Map.of("refreshToken",nativeToken.refreshToken())).andExpect(status().isOk());entities.clear();assertThat(db.queryForMap("SELECT overall_expires_at,idle_expires_at,last_activity_at FROM user_sessions WHERE id=?",nativeId)).isEqualTo(before);
 }
 @Test @Tag("malicious") void expiredIdleAndOverallDenyOtherwiseValidAccessAndRefresh()throws Exception{
  for(String field:List.of("idle_expires_at","overall_expires_at")){var token=login(account());db.update("UPDATE user_sessions SET "+field+"=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE id=?",sid(token));entities.clear();me(token,401);postJson("/api/v1/auth/refresh",Map.of("refreshToken",token.refreshToken())).andExpect(status().isUnauthorized());}
 }
 @Test @Tag("creative") void onlyExplicitActivityExtendsIdleAndNeverOverall()throws Exception{
  var token=login(account());UUID id=sid(token);db.update("UPDATE user_sessions SET last_activity_at=CURRENT_TIMESTAMP-INTERVAL '2 minutes',idle_expires_at=CURRENT_TIMESTAMP+INTERVAL '10 minutes' WHERE id=?",id);var before=db.queryForMap("SELECT last_activity_at,idle_expires_at,overall_expires_at FROM user_sessions WHERE id=?",id);me(token,200);assertThat(db.queryForMap("SELECT last_activity_at,idle_expires_at,overall_expires_at FROM user_sessions WHERE id=?",id)).isEqualTo(before);
  mvc.perform(post("/api/v1/auth/activity").header("Authorization","Bearer "+token.accessToken()).contentType("application/json").content(json.writeValueAsString(Map.of("timestamp","2099-01-01T00:00:00Z")))).andExpect(status().isNoContent());var after=db.queryForMap("SELECT last_activity_at,idle_expires_at,overall_expires_at FROM user_sessions WHERE id=?",id);assertThat(after.get("overall_expires_at")).isEqualTo(before.get("overall_expires_at"));assertThat(((java.sql.Timestamp)after.get("last_activity_at")).toInstant()).isBefore(Instant.now().plusSeconds(5));assertThat(after.get("idle_expires_at")).isNotEqualTo(before.get("idle_expires_at"));
 }
 @Test @Tag("confused") void staleLoginNeedsRealPasswordProofForLogoutAll()throws Exception{
  String email=account();TokenResponse first=login(email),second=login(email);db.update("UPDATE user_sessions SET reauthenticated_at=CURRENT_TIMESTAMP-INTERVAL '11 minutes' WHERE id=?",sid(first));
  mvc.perform(post("/api/v1/auth/logout-all").header("Authorization","Bearer "+first.accessToken())).andExpect(status().isForbidden());
  mvc.perform(post("/api/v1/auth/reauthenticate").header("Authorization","Bearer "+first.accessToken()).contentType("application/json").content(json.writeValueAsString(Map.of("password","incorrect")))).andExpect(status().isForbidden());me(first,200);
  mvc.perform(post("/api/v1/auth/reauthenticate").header("Authorization","Bearer "+first.accessToken()).contentType("application/json").content(json.writeValueAsString(Map.of("password",password)))).andExpect(status().isNoContent());
  mvc.perform(post("/api/v1/auth/logout-all").header("Authorization","Bearer "+first.accessToken())).andExpect(status().isNoContent());entities.clear();me(first,401);me(second,401);postJson("/api/v1/auth/refresh",Map.of("refreshToken",second.refreshToken())).andExpect(status().isUnauthorized());
 }
 @Test @Tag("malicious") void sessionOwnershipAndRevocationHavePersistedEffects()throws Exception{
  String one=account(),two=account();TokenResponse a=login(one),b=login(two);mvc.perform(delete("/api/v1/auth/sessions/"+sid(b)).header("Authorization","Bearer "+a.accessToken())).andExpect(status().isNotFound());me(b,200);
  mvc.perform(delete("/api/v1/auth/sessions/"+sid(a)).header("Authorization","Bearer "+a.accessToken())).andExpect(status().isNoContent());entities.clear();me(a,401);me(b,200);
 }
 @Test @Tag("happy") void passwordChangeRevokesAllSessionsAndAllowsOnlyNewPassword()throws Exception{
  String email=account();TokenResponse first=login(email),second=login(email);String next="A different synthetic EF password 🌊";
  mvc.perform(post("/api/v1/auth/change-password").header("Authorization","Bearer "+first.accessToken()).contentType("application/json").content(json.writeValueAsString(Map.of("currentPassword","wrong","newPassword",next)))).andExpect(status().isForbidden());me(first,200);
  mvc.perform(post("/api/v1/auth/change-password").header("Authorization","Bearer "+first.accessToken()).contentType("application/json").content(json.writeValueAsString(Map.of("currentPassword",password,"newPassword",next)))).andExpect(status().isNoContent());entities.clear();me(first,401);me(second,401);postJson("/api/v1/auth/login",Map.of("email",email,"password",password)).andExpect(status().isUnauthorized());postJson("/api/v1/auth/login",Map.of("email",email,"password",next)).andExpect(status().isOk());
 }
 @Test @Tag("malicious") void suspensionAndRoleChangesInvalidateExistingTokens()throws Exception{
  String email=account();var t=login(email);db.update("UPDATE users SET status='SUSPENDED' WHERE email=?",email);entities.clear();me(t,401);postJson("/api/v1/auth/login",Map.of("email",email,"password",password)).andExpect(status().isUnauthorized());db.update("UPDATE users SET status='ACTIVE' WHERE email=?",email);db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name='MODERATOR'",uid(email));entities.clear();me(t,401);var elevated=login(email);mvc.perform(get("/api/v1/admin/dashboard").header("Authorization","Bearer "+elevated.accessToken())).andExpect(status().isForbidden());
 }
 @Test @Tag("confused") void malformedHashAndUnknownUserHaveSameGenericError()throws Exception{
  String email=account();db.update("UPDATE users SET password_hash='{pbkdf2}not-hex' WHERE email=?",email);entities.clear();for(String candidate:List.of(email,"unknown@example.test"))postJson("/api/v1/auth/login",Map.of("email",candidate,"password",password)).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.message").value("Invalid email or password"));
 }
 @Test @Tag("creative") void securityInventoryHasSafeLabelsNoTokensAndOwnerOnlyEvents()throws Exception{
  String email=account();var token=login(email);var response=mvc.perform(get("/api/v1/auth/sessions").header("Authorization","Bearer "+token.accessToken())).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertThat(response).contains("دستگاه 🌊synthetic").doesNotContain(token.refreshToken(),"refreshTokenHash");
  var events=mvc.perform(get("/api/v1/auth/security-events").header("Authorization","Bearer "+token.accessToken())).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertThat(events).contains("LOGIN_SUCCESS").doesNotContain(email,password,token.refreshToken(),token.accessToken());
 }
 @Test @Tag("malicious") void browserCookieWritesRejectMissingHeaderAndHostileOrigins()throws Exception{
  String email=account();for(String origin:List.of("https://evil.example","http://localhost.evil.test:8081","null"))mvc.perform(post("/api/v1/auth/web/login").header("Origin",origin).header("X-GreenOcean-CSRF","1").contentType("application/json").content(json.writeValueAsString(Map.of("email",email,"password",password)))).andExpect(status().isForbidden());
  mvc.perform(post("/api/v1/auth/web/logout").header("Origin","http://localhost:8081")).andExpect(status().isForbidden());mvc.perform(post("/api/v1/auth/web/logout").header("Origin","http://localhost:8081").header("X-GreenOcean-CSRF","1")).andExpect(status().isNoContent()).andExpect(header().string("Set-Cookie",org.hamcrest.Matchers.containsString("Max-Age=0")));
 }
 @Test @Tag("confused") void recoveryIsSingleUseBoundToOwnerAndRevokesOldSessions()throws Exception{
  String email=account(),other=account();TokenResponse owner=login(email),unrelated=login(other);assistance.requestPasswordReset(new com.greenocean.backend.assistance.dto.EmailRequest(email));String raw=cipher.decrypt(db.queryForObject("SELECT payload->>'encrypted' FROM email_outbox WHERE recipient=? AND template_key='password-reset'",String.class,email));String next="A reset synthetic EF passphrase";
  postJson("/api/v1/account-assistance/password-reset/confirm",Map.of("token",raw,"newPassword",next,"userId",uid(other))).andExpect(status().isOk());entities.clear();me(owner,401);me(unrelated,200);postJson("/api/v1/account-assistance/password-reset/confirm",Map.of("token",raw,"newPassword",next)).andExpect(status().isBadRequest());
 }
 @Test @Tag("malicious") void replacedOrSuspendedRecoveryFailsWithoutChangingPassword()throws Exception{
  String email=account();assistance.requestPasswordReset(new com.greenocean.backend.assistance.dto.EmailRequest(email));String old=cipher.decrypt(db.queryForObject("SELECT payload->>'encrypted' FROM email_outbox WHERE recipient=? AND template_key='password-reset'",String.class,email));assistance.requestPasswordReset(new com.greenocean.backend.assistance.dto.EmailRequest(email));postJson("/api/v1/account-assistance/password-reset/confirm",Map.of("token",old,"newPassword","A reset synthetic EF passphrase")).andExpect(status().isBadRequest());String raw=cipher.decrypt(db.queryForObject("SELECT payload->>'encrypted' FROM email_outbox WHERE recipient=? AND template_key='password-reset'",String.class,email));db.update("UPDATE users SET status='SUSPENDED' WHERE email=?",email);entities.clear();postJson("/api/v1/account-assistance/password-reset/confirm",Map.of("token",raw,"newPassword","A reset synthetic EF passphrase")).andExpect(status().isBadRequest());
 }
 @Test @Tag("malicious") void pendingSessionNeedsFreshLoginAfterRealActivation()throws Exception{
  String email="ef-pending-"+UUID.randomUUID()+"@example.test";registration.register(new RegisterRequest(email,password,null,null,null,"IR",null,null,true,1));entities.clear();var old=login(email);String code=cipher.decrypt(db.queryForObject("SELECT payload->>'encrypted' FROM email_outbox WHERE recipient=? AND template_key='email-verification'",String.class,email));postJson("/api/v1/account-assistance/email-verification/confirm",Map.of("email",email,"code",code)).andExpect(status().isOk());entities.clear();
  mvc.perform(get("/api/v1/identity").header("Authorization","Bearer "+old.accessToken())).andExpect(status().isOk()).andExpect(jsonPath("$.sessionRequiresSignIn").value(true));
  var fresh=json.readValue(postJson("/api/v1/auth/refresh",Map.of("refreshToken",old.refreshToken())).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(),TokenResponse.class);assertThat(db.queryForObject("SELECT session_scope FROM user_sessions WHERE id=?",String.class,sid(fresh))).isEqualTo("PENDING");mvc.perform(get("/api/v1/posts/feed").header("Authorization","Bearer "+fresh.accessToken())).andExpect(status().isForbidden());
  var signedIn=login(email);assertThat(db.queryForObject("SELECT session_scope FROM user_sessions WHERE id=?",String.class,sid(signedIn))).isEqualTo("MEMBER");
 }

}
